import math
from fractions import Fraction

def uniform_map(hq, hkv):
    if hq <= 0 or hkv <= 0:
        raise ValueError('head counts must be positive')
    if hq % hkv != 0:
        raise ValueError('uniform mapping requires divisibility')
    g = hq // hkv
    return tuple(h // g for h in range(hq))

def groups_of(mapping, hkv):
    groups = [[] for _ in range(hkv)]
    for h, m in enumerate(mapping):
        if m < 0 or m >= hkv:
            raise ValueError('mapping outside kv head range')
        groups[m].append(h)
    if any(len(g) == 0 for g in groups):
        raise ValueError('unused kv head in uniform test mapping')
    return groups

def grouped_attention(q, k, v, mapping, visible=None):
    mcount = len(q)
    hq = len(q[0])
    hkv = len(k[0])
    dv = len(v[0][0])
    dk = len(k[0][0])
    groups = groups_of(mapping, hkv)
    loads = 0
    out = [[[0.0 for _ in range(dv)] for _ in range(hq)] for _ in range(mcount)]
    for i in range(mcount):
        vis = list(range(len(k))) if visible is None else list(visible[i])
        acc = [[] for _ in range(hq)]
        for m in range(hkv):
            for j in vis:
                kk = k[j][m]
                vv = v[j][m]
                loads += 1
                for h in groups[m]:
                    score = 0.0
                    for c in range(dk):
                        score += q[i][h][c] * kk[c]
                    score = score / math.sqrt(dk)
                    acc[h].append((score, vv))
        for h in range(hq):
            if not acc[h]:
                continue
            mx = max(item[0] for item in acc[h])
            ws = [math.exp(item[0] - mx) for item in acc[h]]
            den = sum(ws)
            for c in range(dv):
                s = 0.0
                for t in range(len(ws)):
                    s += ws[t] * acc[h][t][1][c]
                out[i][h][c] = s / den
    return out, loads

def dense_attention(q, k_exp, v_exp, visible=None):
    mcount = len(q)
    hq = len(q[0])
    dv = len(v_exp[0][0])
    dk = len(k_exp[0][0])
    out = [[[0.0 for _ in range(dv)] for _ in range(hq)] for _ in range(mcount)]
    for i in range(mcount):
        vis = list(range(len(k_exp))) if visible is None else list(visible[i])
        for h in range(hq):
            if not vis:
                continue
            z = []
            for j in vis:
                s = 0.0
                for c in range(dk):
                    s += q[i][h][c] * k_exp[j][h][c]
                z.append(s / math.sqrt(dk))
            mx = max(z)
            ws = [math.exp(s - mx) for s in z]
            den = sum(ws)
            for c in range(dv):
                s = 0.0
                for t, j in enumerate(vis):
                    s += ws[t] * v_exp[j][h][c]
                out[i][h][c] = s / den
    return out

def expand_kv(k, v, mapping):
    k_exp = []
    v_exp = []
    for j in range(len(k)):
        k_exp.append([list(k[j][mapping[h]]) for h in range(len(mapping))])
        v_exp.append([list(v[j][mapping[h]]) for h in range(len(mapping))])
    return k_exp, v_exp

def max_delta(a, b):
    best = 0.0
    for i in range(len(a)):
        for h in range(len(a[i])):
            for c in range(len(a[i][h])):
                d = abs(a[i][h][c] - b[i][h][c])
                if d > best:
                    best = d
    return best

def local_kv_sets(hq, hkv, tp):
    mapping = uniform_map(hq, hkv)
    if hq % tp != 0:
        raise ValueError('test case requires divisible query heads')
    per = hq // tp
    sets = []
    for r in range(tp):
        qh = range(r * per, (r + 1) * per)
        sets.append(tuple(sorted(set(mapping[h] for h in qh))))
    return tuple(sets)

def main():
    q = [[[0.5, -0.2], [0.1, 0.3], [-0.4, 0.25], [0.7, -0.1]]]
    k = [
        [[0.2, 0.1], [-0.3, 0.4]],
        [[-0.1, 0.5], [0.2, -0.6]],
        [[0.4, -0.2], [0.1, 0.3]],
    ]
    v = [
        [[0.3, -0.1], [0.2, 0.4]],
        [[-0.2, 0.25], [0.5, -0.3]],
        [[0.1, 0.6], [-0.4, 0.2]],
    ]
    mapping = uniform_map(4, 2)
    if groups_of(mapping, 2) != [[0, 1], [2, 3]]:
        raise AssertionError('uniform GQA grouping mismatch')
    got, loads = grouped_attention(q, k, v, mapping)
    k_exp, v_exp = expand_kv(k, v, mapping)
    ref = dense_attention(q, k_exp, v_exp)
    delta = max_delta(got, ref)
    if delta > 1e-12:
        raise AssertionError('grouped map differs from dense reference')
    if loads != 2 * 3 * 1:
        raise AssertionError('grouped K/V load accounting mismatch')

    mqa_map = uniform_map(4, 1)
    k_mqa = [[k[j][0]] for j in range(len(k))]
    v_mqa = [[v[j][0]] for j in range(len(v))]
    mqa_got, mqa_loads = grouped_attention(q, k_mqa, v_mqa, mqa_map)
    k_mqa_exp, v_mqa_exp = expand_kv(k_mqa, v_mqa, mqa_map)
    mqa_ref = dense_attention(q, k_mqa_exp, v_mqa_exp)
    if max_delta(mqa_got, mqa_ref) > 1e-12:
        raise AssertionError('MQA map decomposition mismatch')
    if mqa_loads != 1 * 3 * 1:
        raise AssertionError('MQA load accounting mismatch')

    k_mha = []
    v_mha = []
    for j in range(len(k)):
        k_mha.append([[0.05 * (m + 1) + 0.02 * j, -0.03 * (m + 1) + 0.01 * j] for m in range(4)])
        v_mha.append([[0.04 * (m + 1) - 0.01 * j, 0.02 * (m + 1) + 0.03 * j] for m in range(4)])
    mha_map = uniform_map(4, 4)
    mha_got, _ = grouped_attention(q, k_mha, v_mha, mha_map)
    mha_ref = dense_attention(q, k_mha, v_mha)
    if max_delta(mha_got, mha_ref) > 1e-12:
        raise AssertionError('MHA identity map mismatch')

    wrong_map = tuple(h % 2 for h in range(4))
    bad_got, _ = grouped_attention(q, k, v, wrong_map)
    bad_delta = max_delta(bad_got, ref)
    if bad_delta <= 1e-6:
        raise AssertionError('wrong head mapping was not detected')

    one_token = 2 * 32 * 8 * 128 * 2
    if one_token != 131072:
        raise AssertionError('per token GQA bytes mismatch')
    if one_token * 4096 != 536870912:
        raise AssertionError('4096 token capacity mismatch')
    if 2 * 32 * 1 * 128 * 2 != 16384:
        raise AssertionError('MQA per token bytes mismatch')

    sets24 = local_kv_sets(24, 6, 4)
    if sets24 != ((0, 1), (1, 2), (3, 4), (4, 5)):
        raise AssertionError('non-divisible local set mismatch')
    total24 = sum(len(s) for s in sets24)
    if total24 != 8:
        raise AssertionError('replicated local head count mismatch')
    naive = max(1, 6 // 4) * 4
    if naive == total24:
        raise AssertionError('naive TP division negative control was not detected')

    sets32 = local_kv_sets(32, 8, 16)
    if any(len(s) != 1 for s in sets32):
        raise AssertionError('TP16 local set should contain one head')
    total32 = sum(len(s) for s in sets32)
    if total32 != 16:
        raise AssertionError('TP16 total physical heads mismatch')
    per_rank_bytes = 2 * 32 * 1 * 128 * 2
    logical_bytes = 8 * per_rank_bytes
    physical_bytes = total32 * per_rank_bytes
    if physical_bytes != 2 * logical_bytes:
        raise AssertionError('TP16 replication ratio mismatch')

    effective_bits = Fraction(2 * 32 + 8 * 4, 32)
    if effective_bits != 3:
        raise AssertionError('quantization metadata arithmetic mismatch')

    correct_proj = 4 * 1 * 4096 * 128 * (32 + 8)
    wrong_proj = 4 * 1 * 4096 * 128 * (8 + 8)
    if correct_proj == wrong_proj:
        raise AssertionError('projection head-count negative control was not detected')

    print('uniform mapping and grouped/dense deltas:', delta, mqa_loads)
    print('negative mapping delta:', bad_delta)
    print('KV bytes per token and at 4096:', one_token, one_token * 4096)
    print('TP24 local sets and total copies:', sets24, total24)
    print('TP16 physical/logical bytes:', physical_bytes, logical_bytes)
    print('scope: CPU scalar arithmetic only; no device execution')

if __name__ == '__main__':
    main()
